import { tokenizeSearchText } from "../../shared.js";
import MiniSearch from "minisearch";
//#region src/client/theme-default/support/local-search.ts
/**
* Loads a serialized local search index with the same options that were used
* to build it (functions are not serialized) plus the default search options.
*/
function loadLocalSearchIndex(json, miniSearch) {
	return MiniSearch.loadJSON(json, {
		fields: [
			"title",
			"titles",
			"text"
		],
		storeFields: ["title", "titles"],
		tokenize: tokenizeSearchText,
		searchOptions: {
			fuzzy: .2,
			prefix: true,
			boost: {
				title: 4,
				text: 2,
				titles: 1
			},
			...miniSearch?.searchOptions
		},
		...miniSearch?.options
	});
}
//#endregion
export { loadLocalSearchIndex };
